(()=>{'use strict';const $=s=>document.querySelector(s),root=$('#ops-content'),msg=$('#ops-message'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rub=n=>(n/100).toLocaleString('ru-RU')+' ₽',day=()=>new Date(Date.now()+10800000).toISOString().slice(0,10),stamp=t=>t===null?'':new Date(t+10800000).toISOString().slice(0,16),time=t=>t===null?'—':new Date(t).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}),api=async(p,b)=>{const r=await fetch('/api/admin/'+p,{method:b?'POST':'GET',headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined,cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка запроса');return d;},run=fn=>async e=>{e?.preventDefault();msg.textContent='';const button=e?.submitter;if(button)button.disabled=true;try{await fn(e);}catch(e){msg.textContent=e.message;}finally{if(button)button.disabled=false;}};
 let selectedDay=day(),config;
 async function workforce(){const current=await api('workforce/current');if(!current.canEdit){const e=current.calculation.employees[0];root.innerHTML='<p>Нажмите «Я на смене» в панели сверху. Завершайте смену со своего телефона.</p>'+(e?`<p>Сегодня: ${(e.worked_ms/3600000).toFixed(2)} ч · ≈ ${rub(e.salary_cents)}</p>`:'');return;}
 let printSlot=$('#print-current-report');if(!printSlot){printSlot=document.createElement('div');printSlot.id='print-current-report';root.before(printSlot);}window.STARTPrint?.mountReport(printSlot);config=await api('workforce/settings');const s=config.settings;
 root.innerHTML=`<label>Дата · Москва<input id="work-date" type="date" value="${esc(selectedDay)}"></label><div id="work-history"></div><details><summary>Правила зарплаты</summary><p class="muted">Применяются к новым рабочим дням. Сегодняшний расчёт использует сохранённые настройки.</p><form id="salary-form"><div class="two"><label>Оплата<select name="payMode"><option value="fixed">Ставка за выход</option><option value="hourly">Почасовая</option></select></label><label>Бонус делить<select name="distribution"><option value="equal">Поровну</option><option value="hours">По отработанному времени</option></select></label><label>Ставка, ₽<input name="fixed" inputmode="decimal" type="number" min="0" step="0.01" required value="${s.fixed_cents/100}"></label><label>За час, ₽<input name="hourly" inputmode="decimal" type="number" min="0" step="0.01" required value="${s.hourly_cents/100}"></label><label>Бонус, %<input name="bonus" type="number" min="0" max="100" step="1" required value="${s.bonus_percent}"></label></div><button type="submit">Сохранить правила</button></form></details><details><summary>Личные учётные записи</summary><p class="muted">У каждого сотрудника должен быть свой логин. Общий station не различает людей.</p><div id="people-list"></div><form id="person-form"><label>Имя<input name="name" required maxlength="80"></label><div class="two"><label>Логин<input name="login" pattern="[a-z][a-z0-9_-]{2,30}" autocomplete="off" required></label><label>Роль<select name="role"><option value="staff">Прокат и кафе</option><option value="waiter">Официант</option><option value="admin">Администратор · полный доступ</option></select></label></div><label>Пароль<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><button type="submit">Добавить сотрудника</button></form></details><details><summary>Telegram · отчёт в 22:00</summary><form id="telegram-form"><label class="check"><input name="enabled" type="checkbox" ${config.telegram.enabled?'checked':''}>Уведомления включены</label><label>Chat ID владельца<input name="chat" inputmode="text" value="${esc(config.telegram.ownerChatId)}"></label><p class="muted">${config.telegram.configured?'Бот настроен на сервере.':'Для отправки нужен токен бота в настройках сервера.'} После закрытия кассы также приходит окончательный расчёт.</p><button type="submit">Сохранить</button></form></details><p><a href="/admin/">Касса и выплаты →</a></p>`;
 $('#work-date').onchange=run(async()=>{selectedDay=$('#work-date').value;await history();});$('#salary-form').elements.payMode.value=s.pay_mode;$('#salary-form').elements.distribution.value=s.distribution;
 $('#salary-form').onsubmit=run(async e=>{const f=e.target.elements;await api('workforce/settings',{revision:s.revision,fixedCents:Math.round(Number(f.fixed.value)*100),hourlyCents:Math.round(Number(f.hourly.value)*100),bonusPercent:Number(f.bonus.value),payMode:f.payMode.value,distribution:f.distribution.value});await workforce();msg.textContent='Правила сохранены для новых дней.';});
 for(const p of config.people){const row=document.createElement('form');row.className='ops-row';row.innerHTML=`<label>${esc(p.login)}<input name="name" aria-label="Имя ${esc(p.login)}" value="${esc(p.name)}" maxlength="80" required></label><label>Доступ<select name="role" aria-label="Доступ ${esc(p.login)}"><option value="staff">Прокат и кафе</option><option value="waiter">Официант</option><option value="admin">Администратор · полный доступ</option></select></label><button type="submit">Сохранить</button>`;row.elements.role.value=p.role;row.onsubmit=run(async e=>{const f=e.target.elements;if(f.role.value!==p.role&&!confirm(`Изменить доступ ${p.login} на «${f.role.selectedOptions[0].textContent}»?`))return;await api('workforce/people',{id:p.id,name:f.name.value,role:f.role.value,expectedRole:p.role});await workforce();msg.textContent='Доступ и имя сохранены.';});$('#people-list').append(row);}

 $('#person-form').onsubmit=run(async e=>{const f=e.target.elements;await api('workforce/people',{name:f.name.value,login:f.login.value,password:f.password.value,role:f.role.value});await workforce();msg.textContent='Личный доступ создан.';});$('#telegram-form').onsubmit=run(async e=>{const f=e.target.elements;await api('telegram-settings',{enabled:f.enabled.checked,ownerChatId:f.chat.value});msg.textContent='Telegram сохранён.';});await history();}
 async function history(){const d=await api('workforce/history?day='+selectedDay),out=$('#work-history');out.innerHTML=`<h2>${d.final?'Итог':'Предварительный расчёт'} · ${rub(d.revenue.cents)}</h2><p class="muted">${esc(d.revenue.source)}. Бонус ${d.settings.bonus_percent}% · ${d.settings.distribution==='hours'?'по времени':'поровну'}.</p>`;if(!d.employees.length)out.insertAdjacentHTML('beforeend','<p>Рабочих смен нет.</p>');for(const e of d.employees){const row=document.createElement('div');row.className='ops-row';row.innerHTML=`<div><strong>${esc(e.name)}</strong><p>${time(e.started_at)} — ${e.active?'На смене':time(e.ended_at)} · ${(e.worked_ms/3600000).toFixed(2)} ч</p><small>База ${rub(e.fixed_cents)} + бонус ${rub(e.bonus_cents)}</small></div><strong>${d.final?'':'≈ '}${rub(e.salary_cents)}</strong>`;for(const w of e.sessions||[]){const b=document.createElement('button');b.textContent='Исправить '+time(w.started_at);b.onclick=()=>correct(w);row.append(b);}out.append(row);}const info=document.createElement('p');info.className='muted';info.textContent=d.report?'Отчёт 22:00: '+({sent:'отправлен',queued:'ожидает отправки',sending:'отправляется',unknown:'статус неизвестен, автоматического повтора нет',error:'Telegram отклонил отправку'}[d.report.status]||d.report.status):'Отчёт в 22:00 ещё не сформирован.';out.append(info);const audit=document.createElement('details');audit.innerHTML='<summary>Журнал изменений</summary>';for(const a of d.audit){const item=document.createElement('details');item.className='audit';item.innerHTML=`<summary>${esc(new Date(a.created_at).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}))} · ${esc(a.login)} · ${esc(a.action)}</summary><p>${esc(a.reason)}</p><pre>До: ${esc(a.before_json)}\nПосле: ${esc(a.after_json)}</pre>`;audit.append(item);}out.append(audit);}
 function correct(w){const dialog=document.createElement('dialog');dialog.innerHTML=`<form><h2>Время сотрудника · Москва</h2><label>Начало<input name="start" type="datetime-local" required value="${stamp(w.started_at)}"></label><label>Окончание · пусто, если на смене<input name="end" type="datetime-local" value="${stamp(w.ended_at)}"></label><label>Причина<input name="reason" required maxlength="300"></label><button type="submit">Сохранить исправление</button><button type="button" class="cancel">Отмена</button><p role="status"></p></form>`;root.append(dialog);dialog.querySelector('.cancel').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=e.target.elements;await api('workforce/correct',{id:w.id,revision:w.revision,startedAt:Date.parse(f.start.value+':00+03:00'),endedAt:f.end.value?Date.parse(f.end.value+':00+03:00'):null,reason:f.reason.value});dialog.close();await history();}catch(e){dialog.querySelector('[role=status]').textContent=e.message;}finally{e.submitter.disabled=false;}};dialog.showModal();}
 let stockData,stockItem,component='base';
 async function stock(){stockData=await api('cafe/stock');root.innerHTML=`<p class="muted">Заказ доступен только после настройки расхода и фактических остатков. На одну порцию укажите готовый товар или все ингредиенты. Каждый вариант и добавка настраиваются отдельно.</p><p><a href="/admin/purchase/">Установить остатки на складе →</a></p><label>Найти блюдо<input id="dish-search" type="search"></label><label>Блюдо<select id="dish-select"></select></label><label>Вариант / добавка<select id="component-select"></select></label><form id="recipe-form"><div id="ingredients"></div><button type="button" id="add-ingredient">+ Ингредиент / товар</button><p class="muted" id="recipe-note"></p><button type="submit">Сохранить расход</button></form>`;const fill=()=>{const q=$('#dish-search').value.toLowerCase(),items=stockData.items.filter(i=>i.name.toLowerCase().includes(q)&&i.active);$('#dish-select').innerHTML=items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('');if(items.some(i=>i.id===stockItem))$('#dish-select').value=stockItem;choose();};$('#dish-search').oninput=fill;$('#dish-select').onchange=choose;$('#component-select').onchange=()=>{component=$('#component-select').value;recipe();};$('#add-ingredient').onclick=()=>ingredient();$('#recipe-form').onsubmit=run(async()=>{const current=stockData.recipes.find(r=>r.item_id===stockItem&&r.component===component),ingredients=[...$('#ingredients').children].map(row=>({id:Number(row.querySelector('select').value),amount:row.querySelector('input').value}));await api('cafe/stock',{itemId:stockItem,component,revision:current?.revision??-1,ingredients});stockData=await api('cafe/stock');recipe();msg.textContent='Расход сохранён. Доступность пересчитана.';});fill();}
 function choose(){stockItem=$('#dish-select').value;const item=stockData.items.find(i=>i.id===stockItem);if(!item){$('#recipe-form').hidden=true;return;}$('#recipe-form').hidden=false;const components=item.variants.length?item.variants.map(v=>['variant:'+v.id,v.name]):[['base','Основная порция']];for(const g of stockData.groups.filter(g=>item.groupIds.includes(g.id)))for(const o of g.options)components.push(['option:'+o.id,g.name+' · '+o.name]);$('#component-select').innerHTML=components.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');if(components.some(([id])=>id===component))$('#component-select').value=component;component=$('#component-select').value;recipe();}
 function recipe(){const r=stockData.recipes.find(r=>r.item_id===stockItem&&r.component===component);$('#ingredients').replaceChildren();for(const i of r?.ingredients||[])ingredient(i);$('#recipe-note').textContent=(r?'Настроено. ':'Ещё не настроено. ')+(component.startsWith('option:')?'Если добавка не расходует склад, сохраните пустой список.':'Расход на одну порцию обязателен.');}
 function ingredient(v){const row=document.createElement('div');row.className='ingredient';row.innerHTML=`<select aria-label="Товар" required><option value="">Выберите товар</option>${stockData.inventory.filter(i=>i.active||i.id===v?.id).map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.unit)} · остаток ${esc(i.current??'не задан')}</option>`).join('')}</select><input aria-label="Расход на порцию" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,3})?" required placeholder="Расход"><button type="button" aria-label="Убрать ингредиент">×</button>`;if(v){row.querySelector('select').value=v.id;row.querySelector('input').value=v.amount/1000;}row.querySelector('button').onclick=()=>row.remove();$('#ingredients').append(row);}
 run(async()=>{const s=await api('session');if(!s.user){root.innerHTML='<p><a href="/admin/">Войти в админку →</a></p>';return;}if($('#operations').dataset.page==='stock')await stock();else await workforce();})();})();
